class Solution {
    public List<String> fizzBuzz(int n) {
        List<String> res = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            boolean d3 = (i % 3 == 0);
            boolean d5 = (i % 5 == 0);
            if (d3 && d5) res.add("FizzBuzz");
            else if (d3) res.add("Fizz");
            else if (d5) res.add("Buzz");
            else res.add(String.valueOf(i));
        }
        return res;
    }
}

